def check_suppressed_292(workspace):
    t = _answer(workspace)
    contexts = [t[max(0, m.start()-300):m.end()+2200] for m in re.finditer(r"ms[- ]drg\s*292", t, re.I)]
    pats = [r"(?:suppressed|unknown)", r"reported[_ ]discharge[_ ]count[^.\n]{0,120}\bnull\b|reported count[^.\n]{0,80}\bnull\b", r"suppression[_ ]flag[^.\n]{0,100}(?:true|1)", r"threshold[^.\n]{0,120}10|10[^.\n]{0,120}(?:threshold|or fewer)|10[- ]or[- ]fewer", r"(?:must not|cannot|not) be treated as zero|unknown.{0,180}(?:not|must not|cannot).{0,60}zero"]
    ok = any(all(re.search(p,c,re.I|re.S) for p in pats) for c in contexts)
    return {"score": 1 if ok else 0, "detail": "all required 292 suppression facts present" if ok else "missing 292 suppression fact"}

def check_evidence_linkage(workspace):
    t = _answer(workspace)
    pats = [r"(?:070022|hosp-070022)", r"ms[- ]drg\s*292", r"(?:null|no reported count|no reported discharge count)", r"(?:suppressed|suppression)", r"ms[- ]drg\s*294", r"(?:reported[_ ]discharge[_ ]count\s*[:=]\s*0|reported discharge count[^\n]{0,40}\b0\b|reports? 0)", r"(?:confirmed[_ ]zero|confirmed zero)"]
    ok = all(re.search(p,t,re.I|re.S) for p in pats)
    return {"score": 1 if ok else 0, "detail": "linked YNHH identifiers and both CMS cells" if ok else "missing linkage evidence"}

