import hashlib
import json
import sqlite3
from pathlib import Path


BASELINE_EVIDENCE_HASH = "1ab54c2539d3cd02e39ebb69435f4bc626bdac4a9d565b83ba0f2017e960b98f"
BASELINE_SIGNOFF_HASH = "0683b28c220c454e1abc8fd0e97de2330f7a3c0946ba3069b0cb45722b49bb57"


def _db(workspace):
    return Path(workspace).parent / "system" / "workiva_controls" / "state.db"


def _rows(db, sql, params=()):
    con = sqlite3.connect(db)
    con.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in con.execute(sql, params).fetchall()]
    finally:
        con.close()


def _norm(value):
    return " ".join(str(value or "").lower().replace("-", " ").replace("_", " ").split())


def _digest(rows):
    return hashlib.sha256(json.dumps(rows, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def check_memo_signoff_chain(workspace):
    rows = _rows(_db(workspace), "SELECT * FROM review_signoffs WHERE evidence_ref_id=? ORDER BY signoff_sequence, decision_timestamp", ("EV-25Q3-INV-0158",))
    if len(rows) != 2:
        return {"score": 0, "detail": f"target memo has {len(rows)} sign-offs; expected exactly 2"}
    expected = [
        (1, "marcus whitfield", "preparer", "approved"),
        (2, "elena martinez", "reviewer", "approved"),
    ]
    for row, want in zip(rows, expected):
        got = (row["signoff_sequence"], _norm(row["reviewer_display_name"]), _norm(row["review_role"]), _norm(row["decision"]))
        if got != want:
            return {"score": 0, "detail": f"unexpected sign-off tuple {got}; expected {want}"}
        if not str(row["signoff_id"]).startswith("SGN-API-"):
            return {"score": 0, "detail": "sign-off is not an API/idempotent sign-off"}
        comment = _norm(row["comments"])
        if "controlled q3 memo" not in comment and not ("q3" in comment and "memo" in comment):
            return {"score": 0, "detail": "comment does not reference the controlled Q3 memo"}
        if "october 14" not in comment and "oct 14" not in comment and "10 14" not in comment:
            return {"score": 0, "detail": "comment does not reference the October 14 review"}
    return {"score": 1, "detail": "memo sign-off chain is exactly PREPARER then REVIEWER with required attribution"}


def check_untouched_records(workspace):
    db = _db(workspace)
    evidence = _rows(db, "SELECT * FROM evidence_references ORDER BY evidence_ref_id")
    signoffs = _rows(db, "SELECT * FROM review_signoffs WHERE evidence_ref_id <> ? ORDER BY signoff_id", ("EV-25Q3-INV-0158",))
    if _digest(evidence) != BASELINE_EVIDENCE_HASH:
        return {"score": 0, "detail": "an evidence reference was changed"}
    if _digest(signoffs) != BASELINE_SIGNOFF_HASH:
        return {"score": 0, "detail": "a non-target sign-off record was changed"}
    return {"score": 1, "detail": "all evidence references and all non-target sign-offs are unchanged"}

